-- Separate community database, never apply to the instrumental-order database.
PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS network_members(id TEXT PRIMARY KEY,display_name TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN('INVITED','ACTIVE','SUSPENDED','CANCELED')),created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS network_memberships(member_id TEXT PRIMARY KEY REFERENCES network_members(id),provider_subscription_id TEXT UNIQUE,status TEXT NOT NULL CHECK(status IN('TRIAL','ACTIVE','PAST_DUE','CANCELED','SUSPENDED')),access_until INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS network_sessions(token_hash TEXT PRIMARY KEY CHECK(length(token_hash)=64),member_id TEXT NOT NULL REFERENCES network_members(id),expires_at INTEGER NOT NULL,revoked_at INTEGER);
CREATE TABLE IF NOT EXISTS network_profiles(member_id TEXT PRIMARY KEY REFERENCES network_members(id),display_name TEXT NOT NULL,bio TEXT NOT NULL DEFAULT '',location TEXT NOT NULL DEFAULT '',genres TEXT NOT NULL DEFAULT '',instruments TEXT NOT NULL DEFAULT '',portfolio_url TEXT NOT NULL DEFAULT '',available INTEGER NOT NULL DEFAULT 0 CHECK(available IN(0,1)),directory_visible INTEGER NOT NULL DEFAULT 0 CHECK(directory_visible IN(0,1)));
CREATE TABLE IF NOT EXISTS network_roles(member_id TEXT NOT NULL REFERENCES network_members(id),role TEXT NOT NULL CHECK(role IN('musician','vocalist','producer','songwriter','ghostwriter','audio_engineer','dj','recording_studio','video_creator','artist')),PRIMARY KEY(member_id,role));
-- Additive migration: retain all existing music role rows and constraints.
CREATE TABLE IF NOT EXISTS network_service_roles(member_id TEXT NOT NULL REFERENCES network_members(id),role TEXT NOT NULL CHECK(role IN('carpenter','contractor','electrician','plumber','painter','handyman','graphic_designer','photographer','web_developer','other_service')),PRIMARY KEY(member_id,role));
CREATE INDEX IF NOT EXISTS network_service_roles_role ON network_service_roles(role,member_id);
CREATE TABLE IF NOT EXISTS network_channels(id TEXT PRIMARY KEY,title TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN('forum','chat')),enabled INTEGER NOT NULL DEFAULT 1 CHECK(enabled IN(0,1)));
CREATE TABLE IF NOT EXISTS network_threads(id TEXT PRIMARY KEY,channel_id TEXT NOT NULL REFERENCES network_channels(id),author_id TEXT NOT NULL REFERENCES network_members(id),title TEXT NOT NULL,created_at INTEGER NOT NULL,hidden INTEGER NOT NULL DEFAULT 0 CHECK(hidden IN(0,1)));
CREATE TABLE IF NOT EXISTS network_posts(id TEXT PRIMARY KEY,thread_id TEXT NOT NULL REFERENCES network_threads(id),author_id TEXT NOT NULL REFERENCES network_members(id),body TEXT NOT NULL,created_at INTEGER NOT NULL,hidden INTEGER NOT NULL DEFAULT 0 CHECK(hidden IN(0,1)));
CREATE TABLE IF NOT EXISTS network_chat_messages(id TEXT PRIMARY KEY,channel_id TEXT NOT NULL REFERENCES network_channels(id),author_id TEXT NOT NULL REFERENCES network_members(id),body TEXT NOT NULL,created_at INTEGER NOT NULL,hidden INTEGER NOT NULL DEFAULT 0 CHECK(hidden IN(0,1)));
CREATE TABLE IF NOT EXISTS network_blocks(blocker_id TEXT NOT NULL REFERENCES network_members(id),blocked_id TEXT NOT NULL REFERENCES network_members(id),PRIMARY KEY(blocker_id,blocked_id),CHECK(blocker_id!=blocked_id));
CREATE TABLE IF NOT EXISTS network_reports(id TEXT PRIMARY KEY,reporter_id TEXT NOT NULL REFERENCES network_members(id),target_kind TEXT NOT NULL CHECK(target_kind IN('profile','thread','post','chat','dm')),target_id TEXT NOT NULL,reason TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'OPEN' CHECK(status IN('OPEN','REVIEWED','RESOLVED')),created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS network_dm(id TEXT PRIMARY KEY,sender_id TEXT NOT NULL REFERENCES network_members(id),recipient_id TEXT NOT NULL REFERENCES network_members(id),body TEXT NOT NULL,created_at INTEGER NOT NULL,hidden INTEGER NOT NULL DEFAULT 0 CHECK(hidden IN(0,1)),CHECK(sender_id!=recipient_id));
CREATE INDEX IF NOT EXISTS network_chat_channel_time ON network_chat_messages(channel_id,created_at);
CREATE INDEX IF NOT EXISTS network_posts_thread_time ON network_posts(thread_id,created_at);
CREATE INDEX IF NOT EXISTS network_dm_recipient_time ON network_dm(recipient_id,created_at);
INSERT OR IGNORE INTO network_channels(id,title,kind) VALUES ('general','General','chat'),('producers','Producers','chat'),('musicians','Musicians','chat'),('vocalists','Vocalists','chat'),('songwriters','Songwriters','chat'),('collaborations','Collaborations','forum'),('feedback','Music Feedback','forum'),('opportunities','Opportunities','forum'),('business','Music Business','forum'),('education','Education and Tutorials','forum');
CREATE TABLE IF NOT EXISTS network_invites(token_hash TEXT PRIMARY KEY CHECK(length(token_hash)=64),member_id TEXT NOT NULL UNIQUE REFERENCES network_members(id),expires_at INTEGER NOT NULL,used_at INTEGER);
CREATE TABLE IF NOT EXISTS network_founding_members(member_id TEXT PRIMARY KEY REFERENCES network_members(id),terms_version TEXT NOT NULL,accepted_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS network_login_keys(key_hash TEXT PRIMARY KEY CHECK(length(key_hash)=64),member_id TEXT NOT NULL UNIQUE REFERENCES network_members(id),created_at INTEGER NOT NULL,revoked_at INTEGER);
CREATE INDEX IF NOT EXISTS network_sessions_member ON network_sessions(member_id);
CREATE TABLE IF NOT EXISTS network_billing_plans(cycle TEXT PRIMARY KEY CHECK(cycle IN('monthly','annual')),provider_plan_id TEXT NOT NULL UNIQUE,price_cents INTEGER NOT NULL CHECK(price_cents IN(499,4999)),currency TEXT NOT NULL CHECK(currency='USD'),enrollment_enabled INTEGER NOT NULL DEFAULT 0 CHECK(enrollment_enabled IN(0,1)));
CREATE TABLE IF NOT EXISTS network_enrollments(id TEXT PRIMARY KEY,member_id TEXT NOT NULL UNIQUE REFERENCES network_members(id),cycle TEXT NOT NULL REFERENCES network_billing_plans(cycle),provider_plan_id TEXT NOT NULL,custom_id TEXT NOT NULL UNIQUE,provider_subscription_id TEXT UNIQUE,approval_url TEXT,terms_version TEXT NOT NULL,created_at INTEGER NOT NULL,status TEXT NOT NULL CHECK(status IN('PENDING','APPROVAL_PENDING','BOUND','REVIEW')));
CREATE TABLE IF NOT EXISTS network_subscription_ledger(member_id TEXT PRIMARY KEY REFERENCES network_members(id),provider_subscription_id TEXT NOT NULL UNIQUE,transaction_id TEXT UNIQUE,access_until INTEGER NOT NULL,manual_hold INTEGER NOT NULL DEFAULT 0 CHECK(manual_hold IN(0,1)),revision INTEGER NOT NULL DEFAULT 0,updated_at INTEGER NOT NULL);
